(() => {
'use strict';const $=s=>document.querySelector(s),core=window.PointGeometry,radicals=window.RadicalLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}const decimal=x=>String(x).replace('.','{,}'),half=x=>Number.isInteger(x)?String(x):(x<0?'-':'')+'\\frac{'+Math.abs(x*2)+'}{2}';
function draw(){const a={x:Number($('#point-ax').value),y:Number($('#point-ay').value)},b={x:Number($('#point-bx').value),y:Number($('#point-by').value)},v=core.measure(a,b);for(const [id,value] of [['ax',a.x],['ay',a.y],['bx',b.x],['by',b.y]])$('#output-'+id).value=value;const A=core.screen(a),B=core.screen(b),M=core.screen(v.midpoint);$('#point-legs').setAttribute('d',`M${A.x} ${A.y}L${B.x} ${A.y}L${B.x} ${B.y}`);$('#point-segment').setAttribute('d',`M${A.x} ${A.y}L${B.x} ${B.y}`);for(const [name,p] of [['a',A],['b',B],['m',M]]){$('#circle-'+name).setAttribute('cx',p.x);$('#circle-'+name).setAttribute('cy',p.y);const label=$('#label-'+name);label.setAttribute('x',p.x+(name==='a'?(v.distance===0?-42:-20):12));label.setAttribute('y',p.y+(name==='m'?24:-12));}$('#label-a').textContent=v.distance===0?String.raw`\(A=B=M\)`:String.raw`\(A\)`;$('#marker-b').style.display=v.distance===0?'none':'';$('#marker-m').style.display=v.distance===0?'none':'';$('#point-geometry-plot').setAttribute('aria-label',`Titik pertama (${a.x}, ${a.y}), titik kedua (${b.x}, ${b.y}), titik tengah (${v.midpoint.x}, ${v.midpoint.y}). Jarak ${v.distance}. Skala kedua sumbu sama.`);math($('#point-addresses'),`A=(${a.x},${a.y}),\\quad B=(${b.x},${b.y})`);math($('#point-changes'),`\\Delta x=${v.dx},\\quad\\Delta y=${v.dy}`);const exact=radicals.texRoot(v.squared),isInteger=Number.isInteger(v.distance);math($('#point-distance'),`d=\\sqrt{(${v.dx})^2+(${v.dy})^2}=${exact}`+(!isInteger?'\\approx'+v.distance.toFixed(4).replace('.','{,}') :''));math($('#point-midpoint'),`M=\\left(${half(v.midpoint.x)},${half(v.midpoint.y)}\\right)`);$('#point-geometry-feedback').textContent=v.distance===0?'Kedua ujung sama. Ruas menyusut menjadi satu titik; jaraknya nol dan titik tengahnya sama dengan kedua ujung.':(v.dx===0?'Ruas tegak: perubahan mendatar nol. ':v.dy===0?'Ruas mendatar: perubahan tegak nol. ':'Garis bantu membentuk segitiga siku-siku. ')+`Panjang sisi bantu mendatar ${Math.abs(v.dx)} dan tegak ${Math.abs(v.dy)}. Titik tengah berada pada ruas dan berjarak setengah panjang ruas dari masing-masing ujung.`+(!isInteger?' Bentuk akar adalah nilai tepat; desimal dibulatkan sampai empat angka di belakang koma.':'');}
for(const id of ['ax','ay','bx','by'])$('#point-'+id).addEventListener('input',draw);
function preset(ax,ay,bx,by){for(const [id,value] of [['ax',ax],['ay',ay],['bx',bx],['by',by]])$('#point-'+id).value=value;draw();}
$('#swap-points').addEventListener('click',()=>preset(Number($('#point-bx').value),Number($('#point-by').value),Number($('#point-ax').value),Number($('#point-ay').value)));$('#vertical-points').addEventListener('click',()=>preset(-2,-3,-2,3));$('#horizontal-points').addEventListener('click',()=>preset(-3,2,3,2));$('#coincident-points').addEventListener('click',()=>preset(2,1,2,1));$('#geometry-reset').addEventListener('click',()=>preset(-2,-1,1,3));draw();
const questions=[
[String.raw`A=(0,0),\ B=(3,4):\ d=?`,[String.raw`7`,String.raw`5`,String.raw`25`],1,'Jumlah kuadrat perubahan adalah dua puluh lima. Jarak adalah akar kuadrat utamanya, yaitu lima.'],
[String.raw`A=(-2,1),\ B=(-2,5):\ d=?`,[String.raw`4`,String.raw`0`,String.raw`\text{Tidak terdefinisi}`],0,'Ruasnya tegak. Perubahan mendatar nol dan panjang perubahan tegak empat. Jaraknya tetap terdefinisi.'],
[String.raw`A=(-3,2),\ B=(1,2):\ M=?`,[String.raw`(-1,2)`,String.raw`(2,0)`,String.raw`(-2,4)`],0,'Rata-rata koordinat mendatar negatif satu, sedangkan koordinat tegaknya tetap dua.'],
[String.raw`\begin{gathered}A=(-2,-1),\ B=(1,3)\\M=?\end{gathered}`,[String.raw`(-\frac12,1)`,String.raw`(-1,2)`,String.raw`(\frac12,1)`],0,'Jumlah koordinat mendatar negatif satu, lalu dibagi dua. Jumlah koordinat tegak dua, lalu dibagi dua.'],
[String.raw`d(A,B)\ \text{dan}\ d(B,A)`,[String.raw`\text{Selalu sama}`,String.raw`\text{Selalu berlawanan tanda}`,String.raw`\text{Tergantung kuadran}`],0,'Menukar ujung membalik tanda kedua selisih, tetapi kuadratnya tidak berubah. Jarak tidak negatif.'],
[String.raw`A=B=(2,1):\ M=?`,[String.raw`(0,0)`,String.raw`(4,2)`,String.raw`(2,1)`],2,'Jika ujung berimpit, titik tengah sama dengan keduanya. Jaraknya nol.'],
[String.raw`A=(0,0),\ B=(1,1):\ d=?`,[String.raw`2`,String.raw`\sqrt2`,String.raw`1`],1,'Panjang ruas langsung adalah akar dua, sedangkan lintasan satu mendatar lalu satu tegak panjangnya dua.'],
[String.raw`\text{Apakah titik tengah selalu bulat?}`,[String.raw`\text{Ya}`,String.raw`\text{Tidak}`],1,'Rata-rata dua koordinat bulat dapat berupa pecahan. Misalnya titik tengah nol dan satu pada sumbu mendatar adalah setengah.']
];const solved=new Set();questions.forEach(([tex,options,answer,reason],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend'),num=document.createElement('span'),formula=document.createElement('span');num.dataset.noEquation='';num.textContent=`Latihan ${i+1}: `;formula.dataset.tex=tex;legend.append(num,formula);box.append(legend);options.forEach((option,j)=>{const label=document.createElement('label'),radio=document.createElement('input'),copy=document.createElement('span');radio.type='radio';radio.name=`geometry-q${i}`;radio.value=String(j);copy.dataset.tex=option;label.append(radio,copy);box.append(label);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+reason;feedback.className=ok?'correct':'incorrect';$('#geometry-progress').textContent=`${solved.size} dari 8 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#geometry-questions').append(box);});$('#geometry-progress').textContent='0 dari 8 latihan pernah dijawab tepat.';
try{$('#geometry-reflection').value=localStorage.getItem('fondasi-point-geometry-reflection')||'';}catch{$('#geometry-save').textContent='Catatan belum dapat dimuat. Salin bila diperlukan.';}$('#geometry-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-point-geometry-reflection',$('#geometry-reflection').value);$('#geometry-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#geometry-save').textContent='Catatan belum dapat disimpan. Salin bila diperlukan.';}});
})();
